INSERT INTO `cultural_activities` (`id`, `eatery_id`, `name`, `type`, `price`, `unit`, `discount_note`, `description`, `image_path`, `created_at`, `updated_at`) VALUES
(1, 49, 'Bắn nỏ, làm bỏng chủ, oản xôi lá mít dâng vua, đúc các hiện vật tiêu biểu xưởng thủ công Âu Lạc', 'experience', 1000000.00, '10 người', NULL, 'Bắn nỏ là biểu tượng cho công nghệ quân sự đỉnh cao của Nhà nước Âu Lạc, được minh chứng qua truyền thuyết nỏ thần An Dương Vương.  Kỹ sư Vũ Đình Thanh đã phục dựng thành công mẫu nỏ dài 2m, sử dụng vuốt rùa làm lẫy nỏ và ống chứa tên, có khả năng bắn đồng loạt hàng chục mũi tên đồng Cổ Loa (mô phỏng công nghệ flechette) với tầm xa lên đến 1.000m, phản ánh sức mạnh bảo vệ chủ quyền và trình độ chế tạo vũ khí tinh xảo của người Việt cổ. \r\n\r\nLàm bỏng chủ (bánh chưng/bánh giầy) và oản xôi lá mít dâng vua liên quan đến thời kỳ Nhà nước Văn Lang (tiền thân và giai đoạn đầu của cộng đồng cư dân Âu Lạc).  Theo truyền thuyết, Lang Liêu đã sáng tạo ra bánh chưng (hình vuông, tượng đất) và bánh giầy (hình tròn, tượng trời) từ gạo nếp để dâng vua Hùng, thể hiện nền văn minh nông nghiệp lúa nước và triết lý âm dương, cha mẹ sinh thành.  Các nghi lễ dâng cúng này khẳng định vai trò của nông nghiệp trong đời sống kinh tế và văn hóa tâm linh của cư dân vùng sông Hồng.\r\n\r\nĐúc các hiện vật tiêu biểu tại các xưởng thủ công Âu Lạc (như Cổ Loa) đã tạo ra những vũ khí và đồ dùng bằng đồng sắc bén, bền chắc.  Các hiện vật khảo cổ gồm mũi tên đồng, lẫy nỏ, rìu chiến và thạp đồng cho thấy trình độ luyện kim phát triển cao, phục vụ cả cho sản xuất nông nghiệp (cày, hái) và chiến đấu. Sự hiện diện của các mũi tên đồng Cổ Loa là bằng chứng vật chất xác thực cho cơ chế hoạt động của nỏ thần và sự thịnh vượng của kỹ thuật chế tác kim loại trong giai đoạn này', NULL, '2026-06-03 16:28:53', '2026-06-03 16:28:53'),
(2, 49, 'Tham quan di tích lịch sử thành cổ loa', 'ticket', 30000.00, '1 người', 'trường hợp học sinh 15 tuổi trở lên, sinh viên , người già 60 tuổi trở lên vé =50%', 'tham quan khu di tích Cổ Loa', NULL, '2026-06-03 16:29:55', '2026-06-03 16:29:55'),
(3, 49, 'Dịch vụ dâng hương', 'service', 1000000.00, '1 người', NULL, NULL, NULL, '2026-06-03 16:30:22', '2026-06-03 16:30:22'),
(4, 49, 'Dịch vụ thuyết minh', 'service', 150000.00, 'đoàn 30 người trở xuống', NULL, NULL, NULL, '2026-06-03 16:30:50', '2026-06-03 16:30:50'),
(5, 49, 'đặt lễ: lẵng hoa, quả; xôi, gà', 'service', NULL, '1 người', NULL, NULL, NULL, '2026-06-03 16:31:04', '2026-06-03 16:31:04');
