(51, NULL, 'Bệnh viện Đa khoa Đông Anh', 'benh-vien-da-khoa-dong-anh', 3, 41, 'Bệnh viện đa khoa hạng I tuyến xã, cung cấp dịch vụ khám chữa bệnh chất lượng cao, trang thiết bị hiện đại và đội ngũ y bác sĩ tận tâm phục vụ nhân dân Đông Anh.', NULL, 'Số 21 Đường Cao Lỗ, Uy Nỗ, Đông Anh, Hà Nội', '02438832445', 'Mở cửa cả ngày (24/7)', 21.1355, 105.8445, 'Bảo hiểm & Dịch vụ', 'https://images.unsplash.com/photo-1587351021759-3e566b6af7cc?auto=format&fit=crop&w=800&q=80', 0, 4.70, 'active', NULL, '2026-07-27 15:03:30', '2026-07-27 15:03:30'),
(52, NULL, 'Trung tâm Y tế Xã Đông Anh', 'trung-tam-y-te-xa-dong-anh', 3, 41, 'Cơ sở y tế dự phòng, tiêm chủng chất lượng cao, quản lý các trạm y tế xã/thị trấn và chăm sóc sức khỏe cộng đồng toàn diện.', NULL, 'Tổ 2, Xã Đông Anh, Đông Anh, Hà Nội', '02438832263', '08:00 - 17:00', 21.139, 105.847, 'Theo quy định y tế', 'https://images.unsplash.com/photo-1519494026892-80bbd2d6fd0d?auto=format&fit=crop&w=800&q=80', 0, 4.70, 'active', NULL, '2026-07-27 15:03:31', '2026-07-27 15:03:31'),
