(1, 54, 'Hệ đào tạo THPT chính quy chuẩn quốc gia', 'Giáo dục toàn diện văn hóa kết hợp với các chương trình tìm hiểu di sản lịch sử Cổ Loa, rèn luyện kỹ năng sống.', 'https://images.unsplash.com/photo-1546410531-bb4caa6b424d?auto=format&fit=crop&w=800&q=80', '3 năm', 'Học phí công lập chuẩn', '2026-07-27 15:03:31', '2026-07-27 15:03:31'),
(2, 54, 'Lớp chọn ngoại ngữ (Tiếng Anh - Tiếng Trung tăng cường)', 'Tập trung nâng cao năng lực giao tiếp và cam kết chuẩn đầu ra IELTS từ 5.5 trở lên hoặc HSK tương đương.', 'https://images.unsplash.com/photo-1516321318423-f06f85e504b3?auto=format&fit=crop&w=800&q=80', '3 năm', '500.000đ / tháng học bổ trợ', '2026-07-27 15:03:31', '2026-07-27 15:03:31'),
(3, 63, 'Hệ THCS Chất lượng cao trọng điểm', 'Mô hình lớp chất lượng cao mũi nhọn của xã, cơ sở vật chất hiện đại, học 2 buổi/ngày định hướng thi vào các trường THPT chuyên.', 'https://images.unsplash.com/photo-1509062522246-3755977927d7?auto=format&fit=crop&w=800&q=80', '4 năm', '1.200.000đ / tháng', '2026-07-27 15:03:31', '2026-07-27 15:03:31'),
