INSERT INTO `ocop_products` (`id`, `eatery_id`, `user_id`, `stall_name`, `seller_name`, `seller_phone`, `bank_name`, `bank_account`, `bank_holder`, `qr_code_path`, `name`, `price`, `unit`, `description`, `image_path`, `star_rating`, `created_at`, `updated_at`, `heritage_year`, `story`, `artisans`, `fun_fact`, `audio_narrative`, `ingredients`, `timeline`) VALUES
(1, 34, 187, 'HTX nông nghiệp dược liệu công nghệ cao KOVI', 'HTX nông nghiệp dược liệu công nghệ cao KOVI', NULL, 'MBBank', '0987654321', 'HTX NÔNG NGHIỆP DƯỢC LIỆU CÔNG NGHỆ CAO KOVI', 'https://img.vietqr.io/image/MB-0987654321-compact.png?accountName=HTX+N%C3%94NG+NGHI%E1%BB%86P+D%C6%AF%E1%BB%A2C+LI%E1%BB%86U+C%C3%94NG+NGH%E1%BB%86+CAO+KOVI&addInfo=TT+HTX+n%C3%B4ng+nghi%E1%BB%87p+d%C6%B0%E1%BB%A3c+li%E1%BB%87u+c%C3%B4ng+ngh%E1%BB%87+cao+KOVI', 'Đông trùng hạ thảo tươi', NULL, NULL, 'Thôn Lộc Hà, xã Đông Anh; QĐ số 2008/QĐ-UBND ngày 7/4/2023', NULL, '4 sao', '2026-07-27 03:31:12', '2026-07-27 09:44:40', 'Năm 2022', 'HTX nông nghiệp dược liệu công nghệ cao KOVI ra đời với sứ mệnh mang đến nguồn dược liệu quý Đông Trùng Hạ Thảo sạch, ứng dụng công nghệ sinh học sấy thăng hoa tiên tiến hàng đầu.', 'hdiuhdiqhdiqhoidddddddddddddddd', 'Quy trình sấy thăng hoa ở nhiệt độ -40 độ C giúp giữ nguyên 99% hàm lượng dược chất Cordycepin và Adenosine quý giá.', 'Chào mừng quý khách đến với HTX nông nghiệp dược liệu công nghệ cao KOVI tại Thôn Lộc Hà, xã Đông Anh. Chúng tôi tự hào mang đến các sản phẩm Đông Trùng Hạ Thảo nuôi cấy công nghệ sinh học cao cấp đạt chứng nhận OCOP 4 sao Cấp Quốc Gia.', 'Nấm Đông Trùng Hạ Thảo sinh học 100%\r\nYến chưng & Mật tinh nghệ tự nhiên', 'Năm 2018 | Nghiên cứu nuôi cấy công nghệ cao\r\nNăm 2022 | Đạt chứng nhận OCOP 4 sao Cấp Quốc Gia QĐ số 2008/QĐ-UBND'),
